/* smash20.ini. letSizeX/Y are the cell as DRAWN, in pixels of the 800x600
   frame -- 25 x 28 against the atlas's own 25.6 x 28.44, so the art is
   drawn at very nearly 1:1. letSpace is the tracking added after each
   glyph's ink, spaceLen the width of a space, lineSpace the extra
   between lines, letBaseLine the font's nominal size. */
#define SF_SMALL_SIZE_X     25.000f   /* letSizeX */
#define SF_SMALL_SIZE_Y     28.000f   /* letSizeY */
#define SF_SMALL_SPACE       1.000f   /* letSpace */
#define SF_SMALL_SPACE_LEN   6.000f   /* spaceLen */
#define SF_SMALL_LINE       -5.000f   /* lineSpace */
#define SF_SMALL_BASELINE   20.000f   /* letBaseLine */
#define SF_SMALL_TEX "Smash20"

/* smash26.ini. letSizeX/Y are the cell as DRAWN, in pixels of the 800x600
   frame -- 25 x 28 against the atlas's own 25.6 x 28.44, so the art is
   drawn at very nearly 1:1. letSpace is the tracking added after each
   glyph's ink, spaceLen the width of a space, lineSpace the extra
   between lines, letBaseLine the font's nominal size. */
#define SF_BIG_SIZE_X     25.000f   /* letSizeX */
#define SF_BIG_SIZE_Y     28.000f   /* letSizeY */
#define SF_BIG_SPACE       0.000f   /* letSpace */
#define SF_BIG_SPACE_LEN   6.000f   /* spaceLen */
#define SF_BIG_LINE        0.000f   /* lineSpace */
#define SF_BIG_BASELINE   25.000f   /* letBaseLine */
#define SF_BIG_TEX "Smash26"

